<?php
declare(strict_types=1);
require_once __DIR__ . '/config/bootstrap.php';

$page = trim((string)($_GET['page'] ?? 'home'), '/');
if ($page === 'admin/logout') { session_destroy(); redirect('home'); }
if ($page === 'admin/login' && $_SERVER['REQUEST_METHOD'] === 'POST') {
    verify_csrf();
    $username = trim((string)($_POST['username'] ?? ''));
    $password = (string)($_POST['password'] ?? '');
    $account = query_one('SELECT * FROM users WHERE username = ? AND is_active = 1 LIMIT 1', [$username]);
    if ($account && password_verify($password, $account['password_hash'])) { session_regenerate_id(true); $_SESSION['user'] = ['id' => $account['id'], 'username' => $account['username'], 'role' => $account['role']]; redirect('admin'); }
    flash('The credentials did not match.', 'error'); redirect('admin/login');
}
if ($page === 'prospect' && $_SERVER['REQUEST_METHOD'] === 'POST') {
    verify_csrf();
    $name = trim((string)($_POST['full_name'] ?? '')); $phone = trim((string)($_POST['phone_number'] ?? '')); $bike = trim((string)($_POST['bike_model'] ?? ''));
    if ($name === '' || strlen($name) > 100 || $phone === '' || strlen($phone) > 30 || $bike === '') { flash('Name, phone, and bike are required.', 'error'); redirect('prospect'); }
    query_exec('INSERT INTO prospects (full_name, nickname, phone_number, bike_model, reason_to_join) VALUES (?, ?, ?, ?, ?)', [$name, trim((string)($_POST['nickname'] ?? '')), $phone, $bike, trim((string)($_POST['reason_to_join'] ?? ''))]);
    flash('Your note is in. We will be in touch.', 'success'); redirect('prospect');
}
if (str_starts_with($page, 'admin') && $page !== 'admin/login') require_admin();
if ($page === 'admin' && $_SERVER['REQUEST_METHOD'] === 'POST') {
    verify_csrf(); $type = $_POST['entity'] ?? ''; $id = (int)($_POST['id'] ?? 0);
    $allowed = ['events', 'gallery', 'officers', 'merchandise', 'prospects', 'users'];
    if (!in_array($type, $allowed, true)) { flash('Unknown admin action.', 'error'); redirect('admin'); }
    if (($_POST['action'] ?? '') === 'delete' && $id > 0 && $type !== 'users') { query_exec("DELETE FROM {$type} WHERE id = ?", [$id]); flash('Record removed.', 'success'); redirect('admin', ['tab' => $type]); }
    if (($_POST['action'] ?? '') === 'status' && $id > 0 && $type === 'prospects') { query_exec('UPDATE prospects SET status = ? WHERE id = ?', [$_POST['status'] ?? 'reviewed', $id]); flash('Prospect status updated.', 'success'); redirect('admin', ['tab' => 'prospects']); }
    if (($_POST['action'] ?? '') === 'save') {
        if ($type === 'events') { $values = [trim($_POST['title'] ?? ''), $_POST['event_date'] ?? '', trim($_POST['location'] ?? ''), trim($_POST['description'] ?? ''), $_POST['status'] ?? 'upcoming']; $id ? query_exec('UPDATE events SET title=?, event_date=?, location=?, description=?, status=? WHERE id=?', [...$values, $id]) : query_exec('INSERT INTO events (title,event_date,location,description,status) VALUES (?,?,?,?,?)', $values); }
        if ($type === 'gallery') { $image = upload_image('image', 'gallery'); $values = [trim($_POST['title'] ?? ''), $image ?: ($_POST['image_path'] ?? ''), $_POST['category'] ?? 'touring']; $id ? query_exec('UPDATE gallery SET title=?, image_path=?, category=? WHERE id=?', [...$values, $id]) : query_exec('INSERT INTO gallery (title,image_path,category) VALUES (?,?,?)', $values); }
        if ($type === 'officers') { $image = upload_image('image', 'officers'); $values = [trim($_POST['name'] ?? ''), trim($_POST['position'] ?? ''), trim($_POST['bio'] ?? ''), $image ?: trim($_POST['image_path'] ?? '')]; $id ? query_exec('UPDATE officers SET name=?, position=?, bio=?, image_path=? WHERE id=?', [...$values, $id]) : query_exec('INSERT INTO officers (name,position,bio,image_path) VALUES (?,?,?,?)', $values); }
        if ($type === 'merchandise') { $image = upload_image('image', 'merchandise'); $values = [trim($_POST['name'] ?? ''), trim($_POST['description'] ?? ''), (float)($_POST['price'] ?? 0), $image ?: trim($_POST['image_path'] ?? ''), (int)($_POST['stock'] ?? 0)]; $id ? query_exec('UPDATE merchandise SET name=?, description=?, price=?, image_path=?, stock=? WHERE id=?', [...$values, $id]) : query_exec('INSERT INTO merchandise (name,description,price,image_path,stock) VALUES (?,?,?,?,?)', $values); }
        flash('Changes saved.', 'success'); redirect('admin', ['tab' => $type]);
    }
}

$publicPages = ['home', 'about', 'gallery', 'events', 'event', 'shop', 'prospect', 'contact'];
if ($page === 'admin/login') { $title = 'Member access | Mischief Outlaws'; require __DIR__ . '/includes/header.php'; ?>
