<?php require __DIR__ . '/includes/footer.php'; exit; }
if (!in_array($page, $publicPages, true) && $page !== 'admin') { http_response_code(404); $page = 'home'; }
$title = match ($page) { 'home' => 'Mischief Outlaws MC', 'about' => 'The Charter | Mischief Outlaws', 'gallery' => 'Garage Archive | Mischief Outlaws', 'events', 'event' => 'Rides & Events | Mischief Outlaws', 'shop' => 'Goods | Mischief Outlaws', 'prospect' => 'Make Contact | Mischief Outlaws', 'contact' => 'Contact | Mischief Outlaws', 'admin' => 'Dashboard | Mischief Outlaws', default => 'Mischief Outlaws MC' };
require __DIR__ . '/includes/header.php';
