$president = array_values(array_filter($officers, static fn(array $officer): bool => strcasecmp($officer['position'], 'President') === 0));
$vice = array_values(array_filter($officers, static fn(array $officer): bool => strcasecmp($officer['position'], 'Vice') === 0));
